{
  "name": "opencode-xgoal",
  "version": "0.0.1",
  "private": true,
  "type": "module",
  "displayName": "OpenCode-XGoal",
  "description": "OpenCode-XGoal: a session-native Goal Controller for OpenCode 2, reproducing Codex's Goal behavioral contract.",
  "main": "index.js",
  "exports": {
    ".": {
      "import": "./index.js"
    },
    "./tui": {
      "import": "./tui.js"
    }
  },
  "scripts": {
    "build": "bun build ./src/index.ts --outdir . --target node --format esm && bun build ./src/tui.tsx --outdir . --target node --format esm",
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "peerDependencies": {
    "@opencode/plugin": "*"
  },
  "devDependencies": {
    "@opentui/solid": "0.5.9",
    "@types/bun": "^1.4.3",
    "solid-js": "1.9.12"
  }
}
